(()=>{'use strict';
const configs={
advocacia:{name:'Advocacia',brand:'Atlas · relacionamento jurídico',subtitle:'Da primeira conversa à formalização, com etapas claras e responsáveis definidos.',note:'Modelo administrativo: triagem e relacionamento. Detalhes de processos, documentos e análise de conflito ficam em ambiente jurídico apropriado.',stages:['Novo contato','Triagem','Conflito / reunião','Proposta','Formalizado'],sources:['Site próprio','Indicação','LinkedIn','Google','Jusbrasil','WhatsApp'],kinds:['Reunião inicial','Retorno administrativo','Alinhamento de proposta'],task:'Realizar retorno administrativo',initial:[['Contato exemplo 01','Indicação',0],['Contato exemplo 02','Site próprio',0],['Contato exemplo 03','LinkedIn',1],['Contato exemplo 04','Google',2],['Contato exemplo 05','Site próprio',2],['Contato exemplo 06','Indicação',3],['Contato exemplo 07','WhatsApp',4]],integrations:[['Jusbrasil','Encaminhamento / validação comercial','A API de dados processuais não comprova integração dos leads do Escritório Online. Atribua a origem manualmente ou negocie acesso específico.'],['Projuris ADV','API conforme plano','Pessoas, atendimentos e tarefas podem ser integrados conforme escopo e habilitação contratada.'],['WhatsApp Business Platform','API oficial','Recebimento e retorno por canal autorizado, com templates quando exigidos. Cobranças e políticas próprias.'],['LinkedIn / Google','Origem de demanda','Links com parâmetros de campanha e formulários do próprio site ajudam a atribuir a origem.']]},
estetica:{name:'Estética',brand:'Aurora · jornada de relacionamento',subtitle:'Organize interesses, avaliações, confirmações e retornos com uma experiência acolhedora.',note:'Modelo administrativo: não registra ficha clínica, imagens de procedimentos ou informações de saúde. Autorizações de contato são apenas exemplos.',stages:['Novo interesse','Em conversa','Avaliação','Agendado','Acompanhamento'],sources:['Site próprio','Instagram','Google','Indicação','Trinks','WhatsApp'],kinds:['Avaliação — agenda demonstrativa','Retorno administrativo','Conversa inicial'],task:'Confirmar próximo passo',initial:[['Contato exemplo 01','Instagram',0],['Contato exemplo 02','Site próprio',0],['Contato exemplo 03','Google',1],['Contato exemplo 04','Trinks',2],['Contato exemplo 05','Indicação',3],['Contato exemplo 06','Instagram',3],['Contato exemplo 07','WhatsApp',4]],integrations:[['Instagram / Facebook','Lead Ads / links de reserva','Captura de formulários via integração habilitada. Um botão de reserva direciona o visitante; não sincroniza qualquer CRM automaticamente.'],['Trinks','API e webhooks','Exige ativação do Conecta Trinks e validação do plano, escopos e eventos disponíveis.'],['Clinicorp','API documentada','Possui endpoint de adição de leads; contrato, autorização e funcionalidades devem ser confirmados.'],['WhatsApp Business Platform','API oficial','Confirmações e relacionamento pelo canal autorizado. Não usar como repositório de informações clínicas.']]},
saude:{name:'Saúde',brand:'Íntegra · agenda e relacionamento',subtitle:'Acompanhe solicitações e organize a jornada administrativa de consultas médicas e odontológicas.',note:'Este CRM não é prontuário. Nenhum diagnóstico, exame, documento ou informação clínica deve ser registrado neste protótipo.',stages:['Solicitação','Em atendimento','Horário proposto','Confirmado','Retorno'],sources:['Site próprio','Doctoralia','Saludia','Google','Indicação','WhatsApp'],kinds:['Consulta — agenda demonstrativa','Avaliação odontológica — demonstração','Retorno administrativo'],task:'Conferir confirmação de horário',initial:[['Contato exemplo 01','Doctoralia',0],['Contato exemplo 02','Site próprio',0],['Contato exemplo 03','Google',1],['Contato exemplo 04','Indicação',2],['Contato exemplo 05','Doctoralia',3],['Contato exemplo 06','WhatsApp',3],['Contato exemplo 07','Site próprio',4]],integrations:[['Doctoralia / Docplanner','API com homologação','Sincronização de agenda para fornecedores de software médico aprovados e com autorização por clínica. Widget/link é uma alternativa inicial.'],['Saludia','Integração não confirmada','Serviço de consultas. Não foi localizada API pública; negociar parceria antes de prometer sincronização.'],['Feegow / Doctoralia','Integração nativa','Conexão documentada entre produtos, com limites. Não implica disponibilidade automática para um CRM próprio.'],['iClinic / Google Agenda','Consulta unidirecional','Integração documentada para conferência da agenda; não representa edição bidirecional do CRM.']]}
};
let niche=new URLSearchParams(location.search).get('nicho')||'advocacia';if(!configs[niche])niche='advocacia';const cfg=configs[niche],key='vereda-demo-v1-'+niche;const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let view='pipeline',search='',source='Todos',toastTimer;
const seed=()=>({contacts:cfg.initial.map(([name,src,stage],i)=>({id:'demo-'+(i+1),name,source:src,stage,email:`contato${i+1}@example.com`,owner:i%3===0?'Coordenação':'Equipe de atendimento',date:'2026-10-'+(19+i%4),consent:i%2===0,done:false})),appointments:[{id:'agenda-1',contact:'demo-4',date:'2026-10-19',time:'10:00',kind:cfg.kinds[0],confirmed:true},{id:'agenda-2',contact:'demo-5',date:'2026-10-19',time:'14:30',kind:cfg.kinds[1],confirmed:false},{id:'agenda-3',contact:'demo-6',date:'2026-10-20',time:'09:30',kind:cfg.kinds[0],confirmed:false}]});
let state;try{const stored=JSON.parse(localStorage.getItem(key));state=stored&&Array.isArray(stored.contacts)&&Array.isArray(stored.appointments)?{contacts:stored.contacts.filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&Number.isInteger(c.stage)&&c.stage>=0&&c.stage<cfg.stages.length&&/^\d{4}-\d{2}-\d{2}$/.test(c.date||'')).slice(0,1000),appointments:stored.appointments.filter(a=>a&&typeof a.id==='string'&&typeof a.contact==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(a.date||'')&&/^\d{2}:\d{2}$/.test(a.time||'')).slice(0,1000)}:seed();}catch{state=seed();}const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Armazenamento indisponível; alterações mantidas apenas nesta sessão.');}};const toast=msg=>{clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,5000);};const displayDate=date=>{const [y,m,d]=date.split('-');return `${d}/${m}/${y}`;};const shortDate=date=>displayDate(date).slice(0,5);const id=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);const normal=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
$('campaigns-link').href='campanhas.html?nicho='+niche;$('profile-link').href='personalizar.html?modelo='+({advocacia:'atlas',estetica:'aurora',saude:'integra'}[niche]);$('niche').value=niche;$('niche').addEventListener('change',e=>location.href='crm.html?nicho='+e.target.value);$('crumb').textContent=cfg.name;$('workspace').textContent=cfg.brand;$('page-subtitle').textContent=cfg.subtitle;$('demo-note').textContent=cfg.note;document.title='Vereda CRM · '+cfg.name;
function stats(){const values=[['Contatos em acompanhamento',state.contacts.length,'Registros de demonstração'],['Compromissos na agenda',state.appointments.length,'Agenda local ilustrativa'],['Retornos autorizados',state.contacts.filter(c=>c.consent).length,'Autorização simulada de WhatsApp'],['Próximas ações',state.contacts.filter(c=>!c.done).length,'Tarefas administrativas abertas']];$('stats').innerHTML=values.map(([a,b,c])=>`<article class="stat"><div class="stat-label">${a}<span>↗</span></div><strong>${b}</strong><small>${c}</small></article>`).join('');}
function toolbar(title,extra=''){return `<div class="view-toolbar"><h2>${title}</h2><div class="tool-controls">${['pipeline','contacts'].includes(view)?`<input type="search" id="search" aria-label="Buscar contato" placeholder="Buscar contato…" value="${esc(search)}"><select id="origin" aria-label="Filtrar origem"><option>Todos</option>${cfg.sources.map(s=>`<option ${s===source?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}${extra}</div></div>`;}
const filtered=()=>state.contacts.filter(c=>(source==='Todos'||c.source===source)&&normal(c.name+' '+c.email).includes(normal(search)));
function pipeline(){return toolbar('Visão por etapa')+`<div class="kanban" aria-label="Funil de relacionamento">${cfg.stages.map((stage,i)=>{const contacts=filtered().filter(c=>c.stage===i);return `<section class="lane"><h3 class="lane-heading">${esc(stage)}<span>${contacts.length}</span></h3>${contacts.length?contacts.map(c=>`<article class="contact-card"><button class="contact-name" data-edit="${esc(c.id)}">${esc(c.name)}</button><span class="source-chip">${esc(c.source)}</span><p class="card-meta">${esc(c.owner)}<br>Próximo passo · ${shortDate(c.date)}</p><div class="card-bottom"><span>${c.consent?'● Retorno autorizado':'○ Conferir canal'}</span>${i<cfg.stages.length-1?`<button data-move="${esc(c.id)}" aria-label="Avançar ${esc(c.name)} para ${esc(cfg.stages[i+1])}">Avançar →</button>`:'<span>Etapa final ✓</span>'}</div></article>`).join(''):'<p class="empty-lane">Nenhum contato nesta etapa</p>'}</section>`;}).join('')}</div>`;}
function contacts(){return toolbar('Todos os contatos','<button class="secondary" id="export">Exportar JSON ↓</button>')+`<div class="table-scroll"><table class="page-table"><thead><tr><th>Contato</th><th>Origem</th><th>Etapa</th><th>Responsável</th><th>Canal de retorno</th><th>Ação</th></tr></thead><tbody>${filtered().map(c=>`<tr><td>${esc(c.name)}<br><small>${esc(c.email||'Sem e-mail')}</small></td><td>${esc(c.source)}${c.model?'<br><small>Modelo: '+esc(c.model)+'</small>':''}${c.context?'<br><small>'+esc(c.context)+'</small>':''}${c.attribution?.campaign?'<br><small>Campanha: '+esc(c.attribution.campaign)+'</small>':''}</td><td>${esc(cfg.stages[c.stage])}</td><td>${esc(c.owner)}</td><td><span class="status-pill ${c.consent?'':'gray'}">${c.consent?'WhatsApp autorizado':'A confirmar'}</span></td><td><button data-edit="${esc(c.id)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="6">Nenhum contato encontrado.</td></tr>'}</tbody></table></div>`;}
function agenda(){const dates=[...new Set(state.appointments.map(a=>a.date))].sort();return toolbar('Agenda administrativa','<button class="secondary" id="new-appointment">+ Compromisso</button>')+(dates.length?dates.map(date=>`<section class="agenda-group"><h3 class="agenda-date">${displayDate(date)}</h3>${state.appointments.filter(a=>a.date===date).sort((a,b)=>a.time.localeCompare(b.time)).map(a=>{const c=state.contacts.find(c=>c.id===a.contact);return `<article class="agenda-item"><time class="agenda-time">${esc(a.time)}</time><div><h3>${esc(c?.name||'Contato excluído')}</h3><p>${esc(a.kind)} · ${esc(c?.owner||'Equipe')}</p></div><button class="secondary" data-confirm="${esc(a.id)}">${a.confirmed?'Confirmado ✓':'Marcar confirmado'}</button><button class="danger" data-remove-appointment="${esc(a.id)}" aria-label="Excluir compromisso de ${esc(c?.name||'contato')}">Excluir</button></article>`;}).join('')}</section>`).join(''):'<div class="empty-state">Nenhum compromisso. Crie o primeiro para experimentar a agenda.</div>');}
function tasks(){return toolbar('Próximas ações')+`<div class="tasks-list">${[...state.contacts].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date)).map(c=>`<label class="task ${c.done?'done':''}"><input type="checkbox" data-task="${esc(c.id)}" ${c.done?'checked':''} aria-label="Concluir ação de ${esc(c.name)}"><span class="task-text"><strong>${esc(cfg.task)} · ${esc(c.name)}</strong><small>${esc(c.owner)} · ${esc(cfg.stages[c.stage])}</small></span><time>${shortDate(c.date)}</time></label>`).join('')||'<div class="empty-state">Nenhuma ação pendente.</div>'}</div>`;}
function integrations(){return toolbar('Canais e possibilidades','<a class="secondary" href="integracoes.html">Pesquisa e fontes ↗</a>')+`<div class="integration-grid">${cfg.integrations.map(([name,type,desc])=>`<article class="integration"><div class="integration-top"><h3>${esc(name)}</h3><span class="status-pill gray">Não conectado</span></div><p>${esc(desc)}</p><a href="integracoes.html">Ver condições e fonte oficial ↗</a><div class="type">${esc(type)}</div></article>`).join('')}</div><p class="form-note">A origem de um contato neste protótipo é ilustrativa. Um rótulo “Doctoralia”, “Trinks” ou “Jusbrasil” não representa importação ou integração ativa.</p>`;}
function render(){stats();$('view-content').innerHTML=({pipeline,contacts,agenda,tasks,integrations}[view])();if($('search'))$('search').addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('search').focus();try{$('search').setSelectionRange(pos,pos);}catch{}});if($('origin'))$('origin').addEventListener('change',e=>{source=e.target.value;render();});if($('export'))$('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({demo:true,nicho:niche,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vereda-demo-'+niche+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportação de dados fictícios preparada.');});if($('new-appointment'))$('new-appointment').addEventListener('click',newAppointment);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('page-title').textContent={pipeline:'Relacionamento, com clareza.',agenda:'Cada encontro, bem organizado.',contacts:'Pessoas no centro da operação.',tasks:'O próximo passo à vista.',integrations:'Canais que se conectam.'}[view];render();}));
const form=$('contact-form'),dialog=$('contact-dialog');$('source-options').innerHTML=cfg.sources.map(s=>`<option>${esc(s)}</option>`).join('');$('stage-options').innerHTML=cfg.stages.map((s,i)=>`<option value="${i}">${esc(s)}</option>`).join('');
function editContact(contactId){form.reset();const c=state.contacts.find(c=>c.id===contactId);$('contact-heading').textContent=c?'Editar contato':'Novo contato';$('delete-contact').hidden=!c;form.elements.id.value=c?.id||'';form.elements.name.value=c?.name||'';form.elements.email.value=c?.email||'';form.elements.source.value=c?.source||cfg.sources[0];form.elements.stage.value=c?.stage||0;form.elements.owner.value=c?.owner||'Equipe de atendimento';form.elements.date.value=c?.date||new Date().toLocaleDateString('en-CA');form.elements.consent.value=String(c?.consent||false);dialog.showModal();}
$('add-contact').addEventListener('click',()=>editContact());form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form),existing=state.contacts.find(c=>c.id===data.get('id'));const contact={id:existing?.id||id(),name:String(data.get('name')).trim(),email:String(data.get('email')).trim(),source:String(data.get('source')),stage:Number(data.get('stage')),owner:String(data.get('owner')),date:String(data.get('date')),consent:data.get('consent')==='true',done:existing?.done||false};if(!contact.name){form.elements.name.focus();return;}if(existing)Object.assign(existing,contact);else state.contacts.push(contact);persist();dialog.close();render();toast('Contato salvo nesta demonstração.');});$('delete-contact').addEventListener('click',()=>{if(!confirm('Excluir este contato de demonstração e seus compromissos?'))return;const cid=form.elements.id.value;state.contacts=state.contacts.filter(c=>c.id!==cid);state.appointments=state.appointments.filter(a=>a.contact!==cid);persist();dialog.close();render();toast('Contato de demonstração excluído.');});
const apForm=$('appointment-form'),apDialog=$('appointment-dialog');$('appointment-kind').innerHTML=cfg.kinds.map(k=>`<option>${esc(k)}</option>`).join('');function newAppointment(){if(!state.contacts.length){toast('Cadastre um contato de demonstração primeiro.');return;}apForm.reset();apForm.elements.date.value=new Date().toLocaleDateString('en-CA');apForm.elements.time.value='10:00';$('appointment-contact').innerHTML=state.contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');apDialog.showModal();}apForm.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(apForm),c=state.contacts.find(c=>c.id===d.get('contact'));if(!c)return;if(state.appointments.some(a=>a.date===d.get('date')&&a.time===d.get('time')&&a.contact===c.id)){toast('Este contato já possui compromisso no mesmo horário.');return;}state.appointments.push({id:id(),contact:c.id,date:String(d.get('date')),time:String(d.get('time')),kind:String(d.get('kind')),confirmed:false});persist();apDialog.close();render();toast('Compromisso salvo apenas na agenda demonstrativa.');});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
$('view-content').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),move=e.target.closest('[data-move]'),confirmButton=e.target.closest('[data-confirm]'),remove=e.target.closest('[data-remove-appointment]');if(edit)editContact(edit.dataset.edit);if(move){const c=state.contacts.find(c=>c.id===move.dataset.move);if(c&&c.stage<cfg.stages.length-1){c.stage++;persist();render();toast('Etapa atualizada.');}}if(confirmButton){const a=state.appointments.find(a=>a.id===confirmButton.dataset.confirm);a.confirmed=!a.confirmed;persist();render();toast(a.confirmed?'Confirmação registrada localmente. Nenhuma mensagem enviada.':'Confirmação removida.');}if(remove&&confirm('Excluir este compromisso de demonstração?')){state.appointments=state.appointments.filter(a=>a.id!==remove.dataset.removeAppointment);persist();render();toast('Compromisso de demonstração excluído.');}});$('view-content').addEventListener('change',e=>{if(e.target.matches('[data-task]')){const c=state.contacts.find(c=>c.id===e.target.dataset.task);c.done=e.target.checked;persist();render();toast(c.done?'Ação concluída.':'Ação reaberta.');}});$('reset').addEventListener('click',()=>{if(!confirm('Restaurar os dados fictícios deste nicho? Suas alterações locais serão removidas.'))return;state=seed();search='';source='Todos';persist();render();toast('Demonstração restaurada.');});render();
})();
